/* DEM · QR code do link do aluno, com o leão do Mentor de Líderes no centro, e o desenho do telão.
   Usado pelo painel do time (aba Perguntas e telão em tela cheia) e pela página diagnostico-mentoria-telao.html.
   O código é calculado pela qrcodejs 1.0.0 (a mesma do telão do Arquétipos), no nível H de correção de erro,
   e desenhado aqui: escuro sobre branco, margem branca de 4 módulos, leão sobre placa redonda navy com anel branco,
   ocupando no máximo 22% da largura do código. O leão vai embutido (é o diagnostico-mentoria-leao.png) para o
   canvas poder ser baixado também com a página aberta do disco. Nada aqui chama o banco nem serviço externo. */
(function (raiz) {
  'use strict';

  const LEAO = 'data:image/png;base64,';
  const ESCURO = '#0B1426';
  const FRACAO_LEAO = 0.22;

  let leaoImg = null;
  const leaoPronto = new Promise(function (ok) {
    const i = new Image();
    i.onload = function () { leaoImg = i; ok(i); };
    i.onerror = function () { ok(null); };
    i.src = LEAO;
  });

  function modelo(texto) {
    if (!raiz.QRCode) throw new Error('A biblioteca do QR code não carregou. Confira a internet e recarregue a página.');
    const div = document.createElement('div');
    const q = new raiz.QRCode(div, { text: texto, width: 64, height: 64, correctLevel: raiz.QRCode.CorrectLevel.H });
    return q._oQRCode;
  }

  /* Desenha o QR no canvas, com módulos inteiros. exato = true: o canvas tem `px` × `px` (a sobra fica no branco);
     exato = false: o canvas fica do tamanho certo do código com a margem, sem branco a mais. */
  function desenhar(canvas, texto, px, exato) {
    const m = modelo(texto), n = m.getModuleCount(), margem = 4;
    const mod = Math.max(1, Math.floor(px / (n + margem * 2)));
    const cod = n * mod;
    if (exato === false) px = cod + margem * 2 * mod;
    const ini = Math.floor((px - cod) / 2);
    canvas.width = px; canvas.height = px;
    const g = canvas.getContext('2d');
    g.fillStyle = '#FFFFFF';
    g.fillRect(0, 0, px, px);
    g.fillStyle = ESCURO;
    for (let r = 0; r < n; r++) {
      for (let c = 0; c < n; c++) if (m.isDark(r, c)) g.fillRect(ini + c * mod, ini + r * mod, mod, mod);
    }
    // placa redonda navy com anel branco fino, e o leão no meio
    const diam = cod * FRACAO_LEAO;
    const cx = px / 2, cy = px / 2;
    const anel = Math.max(1.5, diam * 0.06);
    g.beginPath(); g.arc(cx, cy, diam / 2, 0, Math.PI * 2); g.fillStyle = '#FFFFFF'; g.fill();
    g.beginPath(); g.arc(cx, cy, diam / 2 - anel, 0, Math.PI * 2); g.fillStyle = ESCURO; g.fill();
    if (leaoImg) {
      const h = (diam - anel * 2) * 0.64;
      const w = h * leaoImg.width / leaoImg.height;
      g.imageSmoothingEnabled = true;
      g.imageSmoothingQuality = 'high';
      g.drawImage(leaoImg, cx - w / 2, cy - h / 2, w, h);
    }
    return canvas;
  }

  // Canvas com tamanho de tela `lado` (em px CSS), nítido em telas de alta densidade.
  // justo = true: o canvas encolhe para o tamanho exato do código (telão); senão fica com `lado` (painel).
  function desenharNaTela(canvas, texto, lado, justo) {
    const dpr = Math.min(3, Math.max(1, raiz.devicePixelRatio || 1));
    desenhar(canvas, texto, Math.round(lado * dpr), !justo);
    canvas.style.width = (canvas.width / dpr) + 'px';
    canvas.style.height = (canvas.height / dpr) + 'px';
    return canvas;
  }

  function baixarPNG(texto, nome) {
    return new Promise(function (ok, falha) {
      try {
        const c = desenhar(document.createElement('canvas'), texto, 1200);
        c.toBlob(function (blob) {
          if (!blob) return falha(new Error('Não conseguimos gerar a imagem.'));
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url; a.download = nome || 'dem-qrcode.png';
          document.body.appendChild(a); a.click(); document.body.removeChild(a);
          setTimeout(function () { URL.revokeObjectURL(url); }, 4000);
          ok();
        }, 'image/png');
      } catch (e) { falha(e); }
    });
  }

  /* ---------- telão: o mesmo desenho na página do telão e na tela cheia do painel ---------- */
  const CSS = [
    '.dem-telao{position:fixed;inset:0;z-index:80;display:flex;flex-direction:column;align-items:center;justify-content:center;',
    'gap:clamp(8px,1.6vh,18px);padding:max(3vh,16px) max(4vw,16px);text-align:center;background:#0B1426;color:#F3EEE3;',
    'font-family:Inter,system-ui,sans-serif;overflow:hidden;-webkit-font-smoothing:antialiased}',
    '.dem-telao[hidden]{display:none!important}',
    '.dem-telao>*{flex-shrink:0;margin:0}',
    '.dem-telao-logo{height:clamp(30px,6vh,64px);width:auto}',
    '.dem-telao-tit{font:600 clamp(12px,2vh,22px)/1.4 Inter,system-ui,sans-serif;letter-spacing:.16em;text-transform:uppercase;color:#D9B872}',
    '.dem-telao-frase{font:500 clamp(24px,5.6vh,64px)/1.08 "EB Garamond",Georgia,serif;color:#F3EEE3;max-width:min(46ch,92vw);text-wrap:balance}',
    '.dem-telao-qr{background:#FFFFFF;padding:clamp(2px,0.4vh,6px);border-radius:10px;line-height:0;box-shadow:0 0 0 1px #D9B872,0 16px 48px rgba(0,0,0,.35)}',
    '.dem-telao-qr canvas{display:block}',
    '.dem-telao-link{font:500 clamp(13px,2.2vh,26px)/1.4 Inter,system-ui,sans-serif;color:#DCD6CA;max-width:92vw;overflow-wrap:anywhere}',
    '.dem-telao-dica{position:absolute;left:0;right:0;bottom:max(1.6vh,10px);font:400 clamp(12px,1.5vh,16px)/1.4 Inter,system-ui,sans-serif;color:#8E97A8}',
    '.dem-telao-sair{position:absolute;top:max(1.6vh,12px);right:max(1.6vw,12px);min-height:44px;padding:0 16px;border-radius:8px;',
    'border:1px solid #2A3654;background:#111C33;color:#D9B872;font:600 14px Inter,system-ui,sans-serif;cursor:pointer}',
    '.dem-telao-sair:focus-visible{outline:2px solid #D9B872;outline-offset:2px}',
    '@media (hover:hover){.dem-telao-sair:hover{border-color:#D9B872}}'
  ].join('');

  function estilo() {
    if (document.getElementById('dem-telao-css')) return;
    const s = document.createElement('style');
    s.id = 'dem-telao-css';
    s.textContent = CSS;
    document.head.appendChild(s);
  }

  function semProtocolo(link) { return String(link).replace(/^https?:\/\//, ''); }

  /* Monta o telão dentro de `el` (que vira a área do telão). opc: { logo, dica (texto do rodapé), sair (texto do botão) } */
  function montarTelao(el, link, opc) {
    opc = opc || {};
    estilo();
    el.classList.add('dem-telao');
    el.innerHTML =
      '<img class="dem-telao-logo" src="' + (opc.logo || 'logo-melid-white.png') + '" alt="Mentor de Líderes">' +
      '<p class="dem-telao-tit">DEM · Diagnóstico Empresarial MELID</p>' +
      '<h1 class="dem-telao-frase">Aponte a câmera do celular para responder</h1>' +
      '<div class="dem-telao-qr" role="img" aria-label="QR code para responder o diagnóstico"><canvas></canvas></div>' +
      '<p class="dem-telao-link"></p>' +
      (opc.dica ? '<p class="dem-telao-dica"></p>' : '') +
      (opc.sair ? '<button type="button" class="dem-telao-sair" hidden></button>' : '');
    el.querySelector('.dem-telao-link').textContent = semProtocolo(link);
    if (opc.dica) el.querySelector('.dem-telao-dica').textContent = opc.dica;
    if (opc.sair) el.querySelector('.dem-telao-sair').textContent = opc.sair;
    ajustarTelao(el, link);
    return el;
  }

  // O QR fica o maior possível no espaço que sobra, sem rolagem
  function ajustarTelao(el, link) {
    const canvas = el.querySelector('.dem-telao-qr canvas');
    if (!canvas || el.hidden) return;
    const caixa = el.querySelector('.dem-telao-qr');
    canvas.style.width = canvas.style.height = '1px';
    const est = getComputedStyle(el), estQr = getComputedStyle(caixa);
    const gap = parseFloat(est.rowGap || est.gap) || 0;
    const padV = parseFloat(est.paddingTop) + parseFloat(est.paddingBottom);
    const padH = parseFloat(est.paddingLeft) + parseFloat(est.paddingRight);
    const padQr = parseFloat(estQr.paddingTop) * 2;
    let outros = 0, n = 0;
    Array.prototype.forEach.call(el.children, function (filho) {
      if (filho === caixa || filho.hidden) return;
      const pos = getComputedStyle(filho).position;
      if (pos === 'absolute' || pos === 'fixed') return;
      outros += filho.getBoundingClientRect().height; n++;
    });
    const altura = el.clientHeight - padV - outros - gap * n - padQr - 4;
    const largura = el.clientWidth - padH - padQr;
    const reserva = el.querySelector('.dem-telao-dica') ? Math.max(24, el.clientHeight * 0.03) : 0;
    const lado = Math.max(120, Math.floor(Math.min(altura - reserva, largura)));
    desenharNaTela(canvas, link, lado, true);
  }

  raiz.DEM_QR = {
    pronto: function () { return leaoPronto; },
    desenhar: desenhar,
    desenharNaTela: desenharNaTela,
    baixarPNG: baixarPNG,
    montarTelao: montarTelao,
    ajustarTelao: ajustarTelao,
    semProtocolo: semProtocolo
  };
})(window);
